/* Helper function to wait for an atomic bit to be set within a timeout */
static bool wait_for_atomic_bit(atomic_t *atomic, int bit, k_timeout_t timeout)
{
	k_timeout_t start_time = k_uptime_get_32();
	while (!atomic_test_bit(atomic, bit)) {
		if (k_uptime_get_32() - start_time >= k_timeout_get_ms(timeout)) {
			return false; /* Timeout */
		}
		k_sleep(K_MSEC(1)); /* Yield to other threads */
	}
	return true; /* Bit set */
}
